// Name: Key Simulation
// ID: cubesterKeySimulation
// Description: Simulate key presses and mouse clicks for the Scratch VM. Use it for re-keybinding, mobile control setups, and automated testing.
// By: CubesterYT <https://scratch.mit.edu/users/CubesterYT/>

(function (Scratch) {
  "use strict";

  const icon =
    "data:image/svg+xml;base64,PD94bWwg...";

  const KEYS = [
    "space",
    "enter",
    "up arrow",
    "down arrow",
    "left arrow",
    "right arrow",
    "a",
    ...
  ];

  const BUTTONS = [
    {
      text: Scratch.translate("left"),
      value: "left",
    },
    ...
  ];

  let canvasWidth = 480;
  let canvasHeight = 360;

  const getCanvas = () => {
    if (Scratch.renderer && Scratch.renderer.canvas) {
      return Scratch.renderer.canvas;
    }
    return null;
  };

  const updateCanvasSize = () => {
    const canvas = getCanvas();
    if (!canvas) {
      return;
    }
    const rect = canvas.getBoundingClientRect();
    if (rect.width > 0 && rect.height > 0) {
      canvasWidth = rect.width;
      canvasHeight = rect.height;
    }
  };

  const getStage = () => {
    const runtime = Scratch.vm && Scratch.vm.runtime;
    return {
      width: runtime && runtime.stageWidth ? runtime.stageWidth : 480,
      height: runtime && runtime.stageHeight ? runtime.stageHeight : 360,
    };
  };

  const getFramerate = () => {
    const frameLoop = Scratch.vm && Scratch.vm.runtime && Scratch.vm.runtime.frameLoop;
    return frameLoop && frameLoop.framerate ? frameLoop.framerate : 30;
  };
```

