const fs = require("fs");
const assert = require("assert");
const vm = require("vm");

const posts = [];
let nextTimer = 0;
const timers = new Map();

const canvas = {
  getBoundingClientRect: () => ({ width: 600, height: 300 }),
};

const Scratch = {
  vm: {
    postIOData: (device, data) => posts.push({ device, data }),
    runtime: {
      stageWidth: 480,
      stageHeight: 360,
      frameLoop: { framerate: 60 },
    },
  },
  renderer: { canvas },
  Cast: {
    toNumber: (n) => Number(n),
    toString: (n) => String(n),
  },
  BlockType: {
    COMMAND: "command",
    REPORTER: "reporter",
    BOOLEAN: "boolean",
    LABEL: "label",
  },
  ArgumentType: {
    STRING: "string",
    NUMBER: "number",
    BOOLEAN: "boolean",
  },
  translate: (x) => (typeof x === "string" ? x : x.default),
  extensions: { register: (ext) => extensions.push(ext) },
};

const extensions = [];
const windowListeners = {};

global.window = {
  addEventListener: (name, fn) => {
    windowListeners[name] = fn;
  },
};
global.ResizeObserver = class {
  observe() {}
};
global.setTimeout = (fn, ms) => {
  const id = ++nextTimer;
  timers.set(id, { fn, ms });
  return id;
};

const code = fs.readFileSync(
  __dirname + "/../project/extensions/CubesterYT/KeySimulation.js",
  "utf-8"
);
vm.runInNewContext(code, {
  Scratch,
  window: global.window,
  ResizeObserver: global.ResizeObserver,
  setTimeout: global.setTimeout,
});

const ext = extensions[0];
assert(ext, "extension registered");
assert.strictEqual(ext.getInfo().id, "cubesterKeySimulation");

const info = ext.getInfo();
assert.strictEqual(info.color1, "#BF0000");
assert.strictEqual(info.color2, "#800000");
assert.ok(info.menuIconURI.startsWith("data:image/svg+xml;base64,"));
assert.ok(info.blockIconURI.startsWith("data:image/svg+xml;base64,"));
const opcodes = info.blocks.filter((b) => typeof b === "object").map((b) => b.opcode);
