const fs = require("fs");
const assert = require("assert");
const vm = require("vm");

const extensions = [];
const documentListeners = {};
const documentObj = {
  visibilityState: "visible",
  addEventListener: (name, fn) => {
    documentListeners[name] = fn;
  },
};

const requests = [];
function makeSentinel() {
  let releaseHandler = null;
  const sentinel = {
    released: false,
    addEventListener(name, fn) {
      if (name === "release") releaseHandler = fn;
    },
    release() {
      sentinel.released = true;
      if (releaseHandler) releaseHandler();
      return Promise.resolve();
    },
    fireRelease() {
      // Simulate the browser releasing the lock (e.g. document hidden)
      sentinel.released = true;
      if (releaseHandler) releaseHandler();
    },
  };
  return sentinel;
}

const navigatorObj = {
  wakeLock: {
    request: (source) => {
      const sentinel = makeSentinel();
      requests.push({ source, sentinel });
      return Promise.resolve(sentinel);
    },
  },
};

const Scratch = {
  vm: {
    runtime: {
      on: () => {},
    },
  },
  extensions: {
    unsandboxed: true,
    register: (ext) => extensions.push(ext),
  },
  Cast: {
    toBoolean: (value) => value === true || String(value).toLowerCase() === "true",
  },
  BlockType: {
    COMMAND: "command",
    BOOLEAN: "boolean",
  },
  ArgumentType: {
    STRING: "string",
  },
  translate: (x) => (typeof x === "string" ? x : x.default),
};

const code = fs.readFileSync("/project/extensions/DNin/wake-lock.js", "utf-8");
vm.runInNewContext(code, {
  Scratch,
  document: documentObj,
  navigator: navigatorObj,
  console,
});

const ext = extensions[0];
assert(ext, "extension registered");
assert.strictEqual(ext.getInfo().id, "dninwakelock");
const opcodes = ext.getInfo().blocks
  .filter((b) => typeof b === "object")
  .map((b) => b.opcode);
assert.deepStrictEqual([...opcodes].sort(), ["isLocked", "setWakeLock"]);

const setVisible = (visible) => {
  documentObj.visibilityState = visible ? "visible" : "hidden";
};
const becomeVisible = () => {
  setVisible(true);
  documentListeners.visibilitychange();
};
const tick = () => new Promise((resolve) => setTimeout(resolve, 0));

(async () => {
  // Initial state: not locked, no requests
  assert.strictEqual(ext.isLocked(), false, "initially not locked");
  assert.strictEqual(requests.length, 0, "no requests initially");

  // Test A: enable while visible acquires a lock
  await ext.setWakeLock({ enabled: "true" });
  assert.strictEqual(requests.length, 1, "enable visible -> one request");
  assert.strictEqual(ext.isLocked(), true, "enabled -> isLocked true");
  assert.strictEqual(requests[0].sentinel.released, false, "sentinel held");
  console.log("A enable-while-visible OK");

  // Test B: disable while visible releases
  await ext.setWakeLock({ enabled: "false" });
  assert.strictEqual(requests[0].sentinel.released, true, "sentinel released");
  assert.strictEqual(requests.length, 1, "disable -> no new request");
  assert.strictEqual(ext.isLocked(), false, "disabled -> isLocked false");
  console.log("B disable-while-visible OK");

  // Test C: browser releases lock while hidden; reacquire on visibility return
  await ext.setWakeLock({ enabled: "true" });
  assert.strictEqual(requests.length, 2, "re-enabled -> second request");
  setVisible(false);
  requests[1].sentinel.fireRelease();
  assert.strictEqual(
    ext.isLocked(),
    true,
    "isLocked reports intended state while hidden"
  );
  assert.strictEqual(requests.length, 2, "no request attempted while hidden");
  becomeVisible();
  await tick();
  assert.strictEqual(requests.length, 3, "reacquired on visibility return");
  assert.strictEqual(ext.isLocked(), true, "reacquired -> isLocked true");
  console.log("C reacquire-on-return OK");

  // Test D: enabling while hidden defers until visible
  await ext.setWakeLock({ enabled: "false" });
  assert.strictEqual(requests.length, 3, "disable -> still 3 requests");
  setVisible(false);
  const deferred = ext.setWakeLock({ enabled: "true" });
  assert.strictEqual(deferred, undefined, "hidden enable returns immediately");
  assert.strictEqual(ext.isLocked(), true, "hidden enable -> intended state true");
  assert.strictEqual(requests.length, 3, "no request while hidden");
  becomeVisible();
  await tick();
  assert.strictEqual(requests.length, 4, "deferred request fires on visible");
  assert.strictEqual(ext.isLocked(), true, "deferred enable acquired");
  console.log("D enable-while-hidden OK");

  // Test E: disabling while hidden is respected, no reacquire after
  setVisible(false);
  ext.stopAll();
  assert.strictEqual(ext.isLocked(), false, "disabled while hidden");
  assert.strictEqual(requests.length, 4, "stopAll while hidden -> no request");
  becomeVisible();
  await tick();
  assert.strictEqual(requests.length, 4, "no reacquire after disable");
  assert.strictEqual(ext.isLocked(), false, "stays disabled");
  console.log("E disable-while-hidden OK");

  // Test F: release while visible resets intended state (no silent reacquire)
  await ext.setWakeLock({ enabled: "true" });
  assert.strictEqual(requests.length, 5, "enabled again");
  setVisible(true);
  requests[4].sentinel.fireRelease();
  assert.strictEqual(
    ext.isLocked(),
    false,
    "release while visible -> reported false"
  );
  await tick();
  assert.strictEqual(
    requests.length,
    5,
    "no automatic reacquire for visible release"
  );
  await ext.setWakeLock({ enabled: "true" });
  assert.strictEqual(requests.length, 6, "re-enable works after visible release");
  assert.strictEqual(ext.isLocked(), true, "re-enabled");
  console.log("F release-while-visible OK");

  console.log("ALL TESTS PASSED");
})().catch((error) => {
  console.error(error);
  process.exit(1);
});

