// Name: XML
// ID: shovelxml
// Description: Create, parse, and interact with XML data, including support for SVG and XHTML.
// By: TheShovel

(function (Scratch) {
  "use strict";

  if (!Scratch.extensions.unsandboxed) {
    throw new Error("XML extension must run unsandboxed");
  }

  const icon =
    "data:image/svg+xml;base64,";

  const MIME_TYPES = {
    XML: "text/xml",
    SVG: "image/svg+xml",
    XHTML: "application/xhtml+xml",
  };

  class XML {
    constructor() {
      this.xmlDocument = null;
      this.xmlError = "";
    }

    getInfo() {
      return {
        id: "shovelxml",
        name: Scratch.translate("XML"),
        color1: "#27AE60",
        color2: "#1D7A30",
        color3: "#14521F",
        menuIconURI: icon,
        blockIconURI: icon,
        docsURI: "https://extensions.turbowarp.org/TheShovel/XML",
        blocks: [
          {
            opcode: "parse",
            blockType: Scratch.BlockType.COMMAND,
            text: Scratch.translate("parse XML [text] as [type]"),
            arguments: {
              text: {
                type: Scratch.ArgumentType.STRING,
                defaultValue: "<note>Hello XML!</note>",
              },
              type: {
                type: Scratch.ArgumentType.STRING,
                menu: "types",
                defaultValue: "XML",
              },
            },
          },
          "---",
          {
            opcode: "isValid",
            blockType: Scratch.BlockType.BOOLEAN,
            text: Scratch.translate("XML is valid?"),
          },
          {
            opcode: "errorMessage",
            blockType: Scratch.BlockType.REPORTER,
            text: Scratch.translate("XML error message"),
          },
          "---",
          {
            opcode: "tagName",
            blockType: Scratch.BlockType.REPORTER,
            text: Scratch.translate("tag name of [path]"),
            arguments: {
              path: {
                type: Scratch.ArgumentType.STRING,
                defaultValue: "",
              },
            },
          },
          {
            opcode: "textContent",
            blockType: Scratch.BlockType.REPORTER,
            text: Scratch.translate("text content of [path]"),
            arguments: {
              path: {
                type: Scratch.ArgumentType.STRING,
                defaultValue: "",
              },
            },
          },
          {
            opcode: "attribute",
            blockType: Scratch.BlockType.REPORTER,
            text: Scratch.translate("attribute [attribute] of [path]"),
            arguments: {
              attribute: {
                type: Scratch.ArgumentType.STRING,
                defaultValue: "id",
              },
              path: {
                type: Scratch.ArgumentType.STRING,
                defaultValue: "",
              },
            },
          },
          "---",
          {
            opcode: "serialize",
            blockType: Scratch.BlockType.REPORTER,
            text: Scratch.translate("XML as text"),
          },
        ],
        menus: {
          types: {
            acceptReporters: true,
            items: ["XML", "SVG", "XHTML"],
          },
        },
      };
    }

    parse(args) {
      const type = String(args.type);
      const mimeType = MIME_TYPES[type] || "text/xml";
      this.loadDocument(String(args.text), mimeType);
    }

    loadDocument(text, mimeType) {
      const parsedDocument = new DOMParser().parseFromString(text, mimeType);
      const parserError = parsedDocument.getElementsByTagName("parsererror")[0];
      if (parserError) {
        this.xmlDocument = null;
        this.xmlError = String(parserError.textContent).trim();
      } else if (!parsedDocument.documentElement) {
        this.xmlDocument = null;
        this.xmlError = "Invalid or empty XML";
      } else {
        this.xmlDocument = parsedDocument;
        this.xmlError = "";
      }
    }

    isValid() {
      return this.xmlDocument !== null;
    }

    errorMessage() {
      return this.xmlError;
    }

    findElement(path) {
      if (!this.xmlDocument || !this.xmlDocument.documentElement) {
        return null;
      }
      let element = this.xmlDocument.documentElement;
      const pathSegments = String(path).split("/");
      for (const segment of pathSegments) {
        const trimmed = segment.trim();
        if (!trimmed) {
          continue;
        }
        element = this.childAtPath(element, trimmed);
        if (!element) {
          return null;
        }
      }
      return element;
    }

    childAtPath(element, segment) {
      const match = segment.match(/^(.*?)\[(\d+)\]$/);
      let tagName = segment;
      let index = 1;
      if (match) {
        tagName = match[1];
        index = Number(match[2]);
      }
      let found = 0;
      for (const child of element.children) {
        if (child.tagName === tagName) {
          found += 1;
          if (found === index) {
            return child;
          }
        }
      }
      return null;
    }

    tagName(args) {
      const element = this.findElement(args.path);
      return element ? element.tagName : "";
    }

    textContent(args) {
      const element = this.findElement(args.path);
      return element ? element.textContent : "";
    }

    attribute(args) {
      const element = this.findElement(args.path);
      if (!element) {
        return "";
      }
      return element.getAttribute(String(args.attribute)) || "";
    }

    serialize() {
      if (!this.xmlDocument) {
        return "";
      }
      return new XMLSerializer().serializeToString(this.xmlDocument);
    }
  }

