"use strict";
const fs = require("fs");
const assert = require("assert");

const makeElement = (tagName, opts = {}) => {
  const element = {
    tagName: tagName,
    children: [],
    textContent: opts.textContent || "",
    attributes: opts.attributes || {},
    getAttribute(name) {
      return Object.prototype.hasOwnProperty.call(this.attributes, name)
        ? String(this.attributes[name])
        : null;
    },
  };
  return element;
};

const makeDocument = ({ root, parserError, serializeResult }) => ({
  documentElement: root || null,
  serializeResult: serializeResult || "",
  getElementsByTagName(tag) {
    if (parserError && tag === "parsererror") {
      return [parserError];
    }
    return [];
  },
});

const SCRATCH_MOCK = {
  extensions: {
    unsandboxed: true,
    register(instance) {
      SCRATCH_MOCK.registeredInstance = instance;
    },
  },
  translate: (value) =>
    typeof value === "string" ? value : value.default || "",
  ArgumentType: {
    STRING: "string",
    NUMBER: "number",
    BOOLEAN: "boolean",
    MATRIX: "matrix",
    NOTE: "note",
    ANGLE: "angle",
    COLOR: "color",
    IMAGE: "image",
  },
  BlockType: {
    BOOLEAN: "boolean",
    BUTTON: "button",
    COMMAND: "command",
    CONDITIONAL: "conditional",
    EVENT: "event",
    HAT: "hat",
    LABEL: "label",
    LOOP: "loop",
    REPORTER: "reporter",
  },
  Cast: {
    toString: (value) => String(value),
    toNumber: (value) => Number(value),
  },
};

// A real-ish tree helper for fixtures.
const buildNoteFixture = () => {
  const body = makeElement("note", {});
  const to = makeElement("to", { textContent: "TurboWarp" });
  const from = makeElement("from", { textContent: "Scratch" });
  const item1 = makeElement("item", { textContent: "first" });
  const item2 = makeElement("item", { textContent: "second", attributes: { id: "42" } });
  item2.attributes = { id: "42" };
  item2.textContent = "second";
  to.children = [];
  body.children = [to, from, item1, item2];
  const note = makeElement("note", { textContent: "TurboWarpScratchfirstsecond" });
  note.children = body.children;
  const root = note;
  return { root };
};

const buildSVGFixture = () => {
  const circle = makeElement("circle", {
    attributes: { cx: "50", cy: "50", r: "40" },
  });
  const svg = makeElement("svg", {});
  svg.children = [circle];
  return { root: svg };
};

const buildXHTMLFixture = () => {
  const body = makeElement("body", {});
  const p = makeElement("p", { textContent: "Hello XHTML" });
  body.children = [p];
  const html = makeElement("html", {});
  html.children = [body];
  return { root: html };
};

const VALID_FIXTURES = {
  "text/xml": buildNoteFixture(),
  "image/svg+xml": buildSVGFixture(),
  "application/xhtml+xml": buildXHTMLFixture(),
};

const ERROR_FIXTURE = makeElement("parsererror", {
  textContent: "\n\n  <msg>error: mismatched tag</msg>\n\n  <line>1</line>\n\n",
});

// Stub DOM globals: maps a (mime, text) pair to a fake parsed document.
const parseCalls = [];
const PARSED_DOCUMENTS = new Map();
const VALID_TEXT = '<note><to>TurboWarp</to></note>';
const INVALID_TEXT = "<note><to>TurboWarp</note>";

global.DOMParser = class {
  parseFromString(text, mimeType) {
    parseCalls.push([mimeType, text]);
    if (text === VALID_TEXT || text === "<svg></svg>" || text === "<html></html>") {
      const key = `${mimeType}\n${text}`;
      if (PARSED_DOCUMENTS.has(key)) {
        return PARSED_DOCUMENTS.get(key);
      }
      const doc = makeDocument(VALID_FIXTURES[mimeType]);
      PARSED_DOCUMENTS.set(key, doc);
      return doc;
    }
    if (text === INVALID_TEXT) {
      const fakeDoc = makeDocument({ root: null, parserError: ERROR_FIXTURE });
      PARSED_DOCUMENTS.set(`${mimeType}\n${text}`, fakeDoc);
      return fakeDoc;
    }
    throw new Error(`Unexpected fixture text: ${text}`);
  }
};

global.XMLSerializer = class {
  serializeToString(doc) {
    return doc.serializeResult || "<serialized/>";
  }
};

const code = fs.readFileSync(
  "/project/extensions/TheShovel/XML.js",
  "utf-8"
);
new Function("Scratch", code)(SCRATCH_MOCK);
const xml = SCRATCH_MOCK.registeredInstance;
assert.ok(xml, "extension should register an instance");

// Block surface check
const info = xml.getInfo();
const opcodes = info.blocks
  .filter((block) => typeof block === "object")
  .map((block) => block.opcode);
for (const expected of [
  "parse",
  "isValid",
  "errorMessage",
  "tagName",
  "textContent",
  "attribute",
  "serialize",
]) {
  assert.ok(opcodes.includes(expected), `missing block ${expected}`);
}
const menuItems = info.menus.types.items;
assert.deepStrictEqual(menuItems, ["XML", "SVG", "XHTML"]);
assert.strictEqual(info.id, "shovelxml");
assert.strictEqual(info.name, "XML");

// Valid parse
xml.parse({ text: VALID_TEXT, type: "XML" });
assert.strictEqual(xml.isValid(), true, "valid XML should be valid");
assert.strictEqual(xml.errorMessage(), "", "valid XML should have no error");

// Tag name / text / attribute reads
assert.strictEqual(xml.tagName({ path: "" }), "note");
assert.strictEqual(xml.tagName({ path: "note" }), "note");
assert.strictEqual(xml.tagName({ path: "note/to" }), "to");
assert.strictEqual(xml.textContent({ path: "note/to" }), "TurboWarp");
assert.strictEqual(xml.textContent({ path: "" }), "TurboWarpScratchfirstsecond");
assert.strictEqual(xml.attribute({ attribute: "id", path: "note/item[2]" }), "42");
assert.strictEqual(xml.attribute({ attribute: "missing", path: "note/item[2]" }), "");
assert.strictEqual(xml.textContent({ path: "note/item[1]" }), "first");
assert.strictEqual(xml.textContent({ path: "note/nope" }), "");
assert.strictEqual(xml.tagName({ path: "note/nope" }), "");
assert.strictEqual(xml.serialize(), "<serialized/>");

// Invalid parse
xml.parse({ text: INVALID_TEXT, type: "XML" });
assert.strictEqual(xml.isValid(), false, "invalid XML should be invalid");
assert.ok(
  xml.errorMessage().length > 0,
  `error message should not be empty, got: ${xml.errorMessage()}`
);
assert.strictEqual(xml.tagName({ path: "" }), "");
assert.strictEqual(xml.textContent({ path: "" }), "");
assert.strictEqual(xml.attribute({ attribute: "id", path: "" }), "");
assert.strictEqual(xml.serialize(), "");

// SVG parse should use the SVG MIME type
xml.parse({ text: "<svg></svg>", type: "SVG" });
assert.strictEqual(xml.isValid(), true);
assert.strictEqual(parseCalls[parseCalls.length - 1][0], "image/svg+xml");
assert.strictEqual(xml.tagName({ path: "svg" }), "svg");
assert.strictEqual(
  xml.attribute({ attribute: "cx", path: "svg/circle" }),
  "50"
);

// XHTML parse should use the XHTML MIME type
xml.parse({ text: "<html></html>", type: "XHTML" });
assert.strictEqual(xml.isValid(), true);
assert.strictEqual(parseCalls[parseCalls.length - 1][0], "application/xhtml+xml");
assert.strictEqual(xml.tagName({ path: "html/body/p" }), "p");
assert.strictEqual(xml.textContent({ path: "html/body/p" }), "Hello XHTML");

console.log("All XML extension behavioral tests passed.");

