class FontManager extends EventEmitter {
  constructor (runtime) {
    super();

    /**
     * Array of added fonts
     * @type {Array<object>}
     */
    this._addedFonts = [];

    /**
     * A reference to the VM's runtime
     * @type {Runtime}
     */
    this._runtime = runtime;
  }

  /**
   * Add a font family to the manager
   * @param {FontFace} fontFace Font face to be added
   * @return {boolean} Returns true on success
   */
  addFont (fontFace) {
    if (this._addedFonts.some(font => font.family === fontFace.family)) {
      return false;
    }

    this._addedFonts.push(fontFace);

    this.emit('change', this._addedFonts);

    return true;
  }

  /**
   * Remove a font family from the manager
   * @param {string} fontFamily Font family to removed from manager
   * @return {boolean} Returns true on success
   */
  removeFont (fontFamily) {
    if (!this._addedFonts.some(font => font.family === fontFamily)) {
      return false;
    }

    this._addedFonts.splice(this._addedFonts.map(font => font.family).indexOf(fontFamily), 1);

    this.emit('change', this._addedFonts);

    return true;
  }

