 * Wrapper for interacting with local storage
 * in Scratch instances which may be running in
 * sandboxed iframes.
 */

const EventEmitter = require('events');

class FontManager extends EventEmitter {
  constructor (runtime) {
    super();

    /**
     * Array of added fonts
     * @type {Array<object>}
     */
    this._addedFonts = [];

    /**
     * A reference to the VM's runtime
     * @type {Runtime}
     */
    this._runtime = runtime;
  }

  /**
   * Add a font family to the manager
   * @param {FontFace} fontFace Font face to be added
   * @return {boolean} Returns true on success
   */
  addFont (fontFace) {
    if (this._addedFonts.some(font => font.family === fontFace.family)) {
      return false;
    }

    this._addedFonts.push(fontFace);

    this.emit('change', this._addedFonts);

    return true;
  }

  /**
   * Remove a font family from the manager
   * @param {string} fontFamily Font family to removed from manager
   * @return {boolean} Returns true on success
   */
  removeFont (fontFamily) {
    if (!this._addedFonts.some(font => font.family === fontFamily)) {
      return false;
    }

    this._addedFonts.splice(this._addedFonts.map(font => font.family).indexOf(fontFamily), 1);

    this.emit('change', this._addedFonts);

    return true;
  }

  /**
   * Return an array of added fonts
   * @return {Array<object>} Array of added fonts
   */
  getAddedFonts () {
    return this._addedFonts;
  }

  /**
   * Adds a system font if not already present
   * @param {string} fontFamily Font to be added
   * @return {boolean} Returns true on success
   */
  addSystemFont (fontFamily) {
    if (this._addedFonts.some(font => font.family === fontFamily)) {
      return false;
    }

    const fontFace = new FontFace(fontFamily, `local("${fontFamily}")` || '');
    this._addedFonts.push(fontFace);

    this.emit('change', this._addedFonts);

    return true;
  }

  /**
   * Add a font family to the manager
   * @param {string} fontFamily Font family to added to manager
   * @param {string} fontURL URL of the font
   * @param {FontFaceDescriptors} descriptors Font descriptors (style, weight, etc)
   * @return {boolean} Returns true on success
   */
  importFont (fontFamily, fontURL, descriptors) {
    const fontFace = new FontFace(fontFamily, `url(${fontURL})`, descriptors);

    return this.addFont(fontFace);
  }
}

module.exports = FontManager;
