// Name: Font Manager
// ID: SPASfontManager
// Description: Add, remove, and manage custom fonts in your projects.
// By: SharkPool <https://scratch.mit.edu/users/SharkPool/>

(function (Scratch) {
  "use strict";

  if (!Scratch.extensions.unsandboxed) {
    throw new Error("Font Manager extension must run unsandboxed");
  }

