  class FontManagerExtension {
    constructor() {
      this.oldFonts = [];
      this.addedFonts = [];
      this.removedFonts = [];

      fontManager.on("change", () => {
        this._updateFonts();
      });
    }

    _updateFonts() {
      const currentFonts = fontManager.getAddedFonts();

      this.addedFonts = currentFonts.filter(
        (font) =>
          !this.oldFonts.some((oldFont) => oldFont.family === font.family)
      );
      this.removedFonts = this.oldFonts.filter(
        (oldFont) =>
          !currentFonts.some((font) => font.family === oldFont.family)
      );

      if (this.addedFonts.length > 0) {
        runtime.startHats("SPASfontManager_whenFontAdded");
      }
      if (this.removedFonts.length > 0) {
        runtime.startHats("SPASfontManager_whenFontRemoved");
      }

      this.oldFonts = currentFonts;
    }

    getInfo() {
      return {
        id: "SPASfontManager",
        name: "Font Manager",
        color1: "#4252C8",
        color2: "#34409F",
        color3: "#2A337F",
        menuIconURI: icon,
        blocks: [
          {
            opcode: "whenFontAdded",
            blockType: Scratch.BlockType.EVENT,
            isEdgeActivated: false,
            text: "when a font is added",
          },
          {
            opcode: "whenFontRemoved",
            blockType: Scratch.BlockType.EVENT,
            isEdgeActivated: false,
            text: "when a font is removed",
          },
          "---",
          {
            opcode: "addSystemFont",
            blockType: Scratch.BlockType.COMMAND,
            text: "add system font [FONT]",
            arguments: {
              FONT: {
                type: Scratch.ArgumentType.STRING,
                menu: "FONTS",
                defaultValue: "Arial",
              },
            },
          },
          {
            opcode: "importFont",
            blockType: Scratch.BlockType.COMMAND,
            text: "import font [FONT] from URL [URL]",
            arguments: {
              FONT: {
                type: Scratch.ArgumentType.STRING,
                defaultValue: "My Font",
              },
              URL: {
                type: Scratch.ArgumentType.STRING,
                defaultValue: "https://example.com/font.ttf",
              },
            },
          },
          {
            opcode: "removeFont",
            blockType: Scratch.BlockType.COMMAND,
            text: "remove font [FONT]",
            arguments: {
              FONT: {
                type: Scratch.ArgumentType.STRING,
                defaultValue: "Arial",
              },
            },
          },
          "---",
          {
            opcode: "getAddedFonts",
            blockType: Scratch.BlockType.REPORTER,
            text: "added fonts",
          },
          {
            opcode: "isFontAdded",
            blockType: Scratch.BlockType.BOOLEAN,
            text: "is font [FONT] added?",
            arguments: {
              FONT: {
                type: Scratch.ArgumentType.STRING,
                defaultValue: "Arial",
              },
            },
          },
          {
            opcode: "getFontDetails",
            blockType: Scratch.BlockType.REPORTER,
            text: "[DETAIL] of font [FONT]",
            arguments: {
              DETAIL: {
                type: Scratch.ArgumentType.STRING,
                menu: "DETAIL",
                defaultValue: "family",
              },
              FONT: {
                type: Scratch.ArgumentType.STRING,
                defaultValue: "Arial",
              },
            },
          },
        ],
        menus: {
          FONTS: {
            acceptReporters: true,
            items: [
              "Arial",
              "Arial Black",
              "Comic Sans MS",
              "Courier New",
              "Georgia",
              "Impact",
              "Times New Roman",
              "Trebuchet MS",
              "Verdana",
              "monospace",
              "sans-serif",
              "serif",
            ],
          },
          DETAIL: {
            acceptReporters: true,
            items: ["family", "style", "weight", "status", "source"],
          },
        },
      };
    }

    addSystemFont(args) {
      const font = Cast.toString(args.FONT);
      const result = fontManager.addSystemFont(font);
      if (result === false) {
        throw new Error(`Could not add system font '${font}'`);
      }
    }

    importFont(args) {
      const font = Cast.toString(args.FONT);
      const url = Cast.toString(args.URL);
      const extension = url.split(".").pop().toLowerCase();
      if (SUPPORTED_EXTS.indexOf(`.${extension}`) === -1) {
        throw new Error(
          `Unsupported font format '.${extension}'. Supported formats: ${SUPPORTED_EXTS.join(", ")}`
        );
      }
      const fontFace = new FontFace(font, `url(${url})`);
      const result = fontManager.addFont(fontFace);
      if (result === false) {
        throw new Error(`Could not add font '${font}'`);
      }
    }

    removeFont(args) {
      const font = Cast.toString(args.FONT);
      const result = fontManager.removeFont(font);
      if (result === false) {
        throw new Error(`Could not remove font '${font}'`);
      }
    }

    getAddedFonts() {
      return JSON.stringify(
        fontManager.getAddedFonts().map((font) => font.family)
      );
    }

    isFontAdded(args) {
      const font = Cast.toString(args.FONT);
      return fontManager
        .getAddedFonts()
        .some((addedFont) => addedFont.family === font);
    }

    getFontDetails(args) {
      const font = Cast.toString(args.FONT);
      const detail = Cast.toString(args.DETAIL);
      const foundFont = fontManager
        .getAddedFonts()
        .find((addedFont) => addedFont.family === font);
      if (!foundFont) {
        return "";
      }
      return `${foundFont[detail] ?? ""}`;
    }
  }

