arguments.content:
const fs = require("fs");
const vm = require("vm");

const code = fs.readFileSync("/project/extensions/SharkPool/Font-Manager.js", "utf-8");

let registered = null;
let unsandboxed = true;
let suppressed = null;
let startHatsCalls = [];
let changeHandler = null;
const addedFonts = [];
const listeners = {};

const fontManagerMock = {
  on: (event, handler) => {
    if (event !== "change") throw new Error(`Unexpected event ${event}`);
    changeHandler = handler;
  },
  getAddedFonts: () => addedFonts.slice(),
  addSystemFont: (family) => {
    if (addedFonts.some((f) => f.family === family)) return false;
    addedFonts.push({ family, style: "normal", weight: "400", status: "loaded", source: "local" });
    changeHandler();
    return true;
  },
  addFont: (face) => {
    if (addedFonts.some((f) => f.family === face.family)) return false;
    addedFonts.push(face);
    changeHandler();
    return true;
  },
  removeFont: (family) => {
    const index = addedFonts.findIndex((f) => f.family === family);
    if (index === -1) return false;
    addedFonts.splice(index, 1);
    changeHandler();
    return true;
  },
};

const Scratch = {
  ext: null,
  extensions: {
    get unsandboxed() {
      return unsandboxed;
    },
    register: (ext) => {
      registered = ext;
    },
  },
  vm: {
    runtime: {
      fontManager: fontManagerMock,
      startHats: (id) => startHatsCalls.push(id),
    },
  },
  Cast: {
    toString: (value) => String(value),
    toNumber: (value) => Number(value),
    toBoolean: (value) => Boolean(value),
  },
  BlockType: {
    COMMAND: "command",
    BOOLEAN: "boolean",
    REPORTER: "reporter",
    EVENT: "event",
  },
  ArgumentType: {
    STRING: "string",
    NUMBER: "number",
    BOOLEAN: "boolean",
  },
  translate: (...args) => args,
};

function createContext() {
  const context = { Scratch, console, FontFace, setTimeout, clearTimeout, Promise };
  context.globalThis = context;
  return vm.createContext(context);
}

function run() {
  vm.runInContext(code, createContext(), { filename: "Font-Manager.js" });
}

const assert = (condition, message) => {
  if (!condition) throw new Error(`ASSERTION FAILED: ${message}`);
};
let tests = 0;

function unsandboxedThrowTest() {
  unsandboxed = false;
  let threw = false;
  try {
    run();
  } catch (e) {
    threw = /must run unsandboxed/.test(String(e && e.message));
  }
  assert(threw, "should throw when unsandboxed is unavailable");
  unsandboxed = true;
  tests++;
}

function blockSurfaceTest() {
  run();
  const info = registered.getInfo();
  assert(info.id === "SPASfontManager", "extension id");
  const blockByOpcode = {};
  for (const block of info.blocks) {
    if (typeof block === "string") continue;
    blockByOpcode[block.opcode] = block;
  }
  const expected = {
    whenFontAdded: Scratch.BlockType.EVENT,
    whenFontRemoved: Scratch.BlockType.EVENT,
    addSystemFont: Scratch.BlockType.COMMAND,
    importFont: Scratch.BlockType.COMMAND,
    removeFont: Scratch.BlockType.COMMAND,
    getAddedFonts: Scratch.BlockType.REPORTER,
    isFontAdded: Scratch.BlockType.BOOLEAN,
    getFontDetails: Scratch.BlockType.REPORTER,
  };
  for (const [opcode, type] of Object.entries(expected)) {
    assert(blockByOpcode[opcode], `block exists: ${opcode}`);
    assert(blockByOpcode[opcode].blockType === type, `block type ${opcode}`);
  }
  assert(typeof blockByOpcode.getFontDetails.arguments.DETAIL.menu === "string", "detail menu");
  assert(blockByOpcode.isFontAdded.blockType === Scratch.BlockType.BOOLEAN, "isFontAdded boolean");
  tests++;
}

function addSystemFontTest() {
  registered.addSystemFont({ FONT: "Arial" });
  assert(addedFonts.length === 1, "system font added");
  assert(addedFonts[0].family === "Arial", "system font family");
  assert(startHatsCalls.includes("SPASfontManager_whenFontAdded"), "whenFontAdded hat fired");

  let threw = false;
  try {
    registered.addSystemFont({ FONT: 123 });
    registered.addSystemFont({ FONT: "Arial" });
  } catch (e) {
    threw = true;
  }
  assert(threw, "duplicate add throws");
  assert(addedFonts.length === 2, "duplicate not added twice");
  tests++;
}

function importFontTest() {
  const before = addedFonts.length;
  registered.importFont({ FONT: "My Font", URL: "https://example.com/font.woff2" });
  assert(addedFonts.length === before + 1, "import font added");
  assert(addedFonts[addedFonts.length - 1].family === "My Font", "import font family");

  for (const ext of [".ttf", ".otf", ".woff", ".woff2"]) {
    const oldLen = addedFonts.length;
    registered.importFont({ FONT: `F${ext}`, URL: `https://example.com/font${ext.toUpperCase()}` });
    assert(addedFonts.length === oldLen + 1, `supported format ${ext}`);
  }

  let threw = false;
  try {
    registered.importFont({ FONT: "Bad", URL: "https://example.com/font.exe" });
  } catch (e) {
    threw = /Unsupported font format/.test(e && e.message);
  }
  assert(threw, "unsupported format throws");

  let duplicateThrew = false;
  try {
    registered.importFont({ FONT: "My Font", URL: "https://example.com/other.ttf" });
  } catch (e) {
    duplicateThrew = /Could not add font/.test(e && e.message);
  }
  assert(duplicateThrew, "duplicate import throws");
  tests++;
}

function removeFontTest() {
  const before = addedFonts.length;
  registered.removeFont({ FONT: "Arial" });
  assert(addedFonts.length === before - 1, "font removed");
  assert(startHatsCalls.includes("SPASfontManager_whenFontRemoved"), "whenFontRemoved hat fired");
  startHatsCalls = [];

  let threw = false;
  try {
    registered.removeFont({ FONT: "Does Not Exist" });
  } catch (e) {
    threw = /Could not remove font/.test(e && e.message);
  }
  assert(threw, "removing missing font throws");
  tests++;
}

function reportersTest() {
  const families = JSON.parse(registered.getAddedFonts());
  assert(Array.isArray(families), "added fonts is a JSON array");
  assert(families.includes("My Font"), "added fonts contains imported font");

  assert(registered.isFontAdded({ FONT: "My Font" }) === true, "isFontAdded true");
  assert(registered.isFontAdded({ FONT: "Nope" }) === false, "isFontAdded false");

  assert(registered.getFontDetails({ FONT: "My Font", DETAIL: "family" }) === "My Font", "details family");
  assert(registered.getFontDetails({ FONT: "My Font", DETAIL: "status" }) === "loaded", "details status");
  assert(registered.getFontDetails({ FONT: "Nope", DETAIL: "family" }) === "", "details missing font");
  assert(registered.getFontDetails({ FONT: "My Font", DETAIL: "nope" }) === "", "details missing detail");
  tests++;
}

function hatTests() {
  // Old fonts snapshot to trigger removal tracking on next change
  changeHandler();
  const oldCount = startHatsCalls.length;
  fontManagerMock.addSystemFont("Comic Sans MS");
  assert(startHatsCalls.includes("SPASfontManager_whenFontAdded"), "hat on external add");
  fontManagerMock.removeFont("Comic Sans MS");
  assert(startHatsCalls.includes("SPASfontManager_whenFontRemoved"), "hat on external remove");
  tests++;
}

unsandboxedThrowTest();
blockSurfaceTest();
addSystemFontTest();
importFontTest();
removeFontTest();
reportersTest();
hatTests();

console.log(`All ${tests} mocked-Scratch test groups passed.`);

