// Minimal SVG rasterizer for the subset used by these icons (rect, path, g, pattern).
// Renders to PNG using zlib (node builtin). Supports: transforms, fill, stroke,
// rounded rects, non-zero fill rule, round/butt caps & joins approximation.
'use strict';
const zlib = require('zlib');

const SS = 4; // supersampling factor

// ---------- path parsing ----------
function parsePath(d) {
  const segs = [];
  const re = /([MLHVZ]|[mlhvz]|-?\.?\d+(?:\.\d+)?(?:[eE][-+]?\d+)?|-?\.\d+)/g;
  let m;
  const tokens = [];
  while ((m = re.exec(d))) tokens.push(m[0]);
  const subs = []; // [{pts:[{x,y}], closed:bool}]
  let curSub = null;
  let x = 0, y = 0, sx = 0, sy = 0;
  let i = 0;
  const num = () => parseFloat(tokens[i++]);
  while (i < tokens.length) {
    let t = tokens[i++];
    if (/^[MLHVZmlhvz]$/.test(t)) {
      if (t === 'Z' || t === 'z') {
        if (curSub) { curSub.closed = true; subs.push(curSub); curSub = null; x = sx; y = sy; }
        continue;
      }
      // handle implicit repeated commands handled below by keeping cmd
      while (t) {
        const c = t;
        if (c === 'M' || c === 'm' || c === 'L' || c === 'l') {
          const dx = i < tokens.length && /^[ml]$/.test(t) ? num() : num();
          const dy = i < tokens.length ? num() : num();
          const nx = (c === 'M' || c === 'L') ? dx : x + dx;
          const ny = (c === 'm' || c === 'l') ? dy : (c === 'M' || c === 'L') ? dy : y + dy;
          if (c === 'M' || c === 'm') { sx = nx; sy = ny; curSub = { pts: [{ x: nx, y: ny }], closed: false }; }
          else if (curSub) curSub.pts.push({ x: nx, y: ny });
          x = nx; y = ny;
        } else if (c === 'H' || c === 'h' || c === 'V' || c === 'v') {
          const v = num();
          let nx = x, ny = y;
          if (c === 'H') nx = v; else if (c === 'h') nx = x + v;
          else if (c === 'V') ny = v; else ny = y + v;
          if (curSub) curSub.pts.push({ x: nx, y: ny });
          x = nx; y = ny;
        } else if (c === 'Z' || c === 'z') {
          if (curSub) { curSub.closed = true; subs.push(curSub); curSub = null; x = sx; y = sy; }
        }
