        if (i < tokens.length && /^[MLHVZmlhvz]$/.test(tokens[i])) t = tokens[i++];
        else if (/^[ml]$/.test(c)) t = 'l';
        else if (/^[ML]$/.test(c)) t = 'L';
        else if (/^[hv]/.test(c)) t = c;
        else if ('Zz'.includes(c)) t = '';
        else t = '';
