function apply(m, x, y) { return { x: m[0] * x + m[2] * y + m[4], y: m[1] * x + m[3] * y + m[5] }; }
function parseTransform(str) {
  let m = ident();
  if (!str) return m;
  const re = /(matrix|translate|scale)\(([^)]*)\)/g;
  let mm;
  while ((mm = re.exec(str))) {
    const nums = mm[2].split(/[\s,]+/).map(Number).filter(n => !isNaN(n));
    if (mm[1] === 'matrix') { m = mul(m, nums); }
    else if (mm[1] === 'translate') m = mul(m, [1, 0, 0, 1, nums[0], nums[1] || 0]);
    else if (mm[1] === 'scale') m = mul(m, [nums[0], 0, 0, nums[1] || nums[0], 0, 0]);
