  pts = pts.concat(ellipsePts(x + w - rx, y + h - ry, rx, ry, Math.PI * 2, Math.PI * 2.5, n));
  pts = pts.concat(ellipsePts(x + rx, y + h - ry, rx, ry, Math.PI * 2.5, Math.PI * 3, n));
