      else this.layer(fill, alpha).fillPoly(subs[0].pts.map(p => apply(tx, p.x, p.y)));
    }
    if (stroke && stroke !== 'none' && sw > 0) {
      const L = this.layer(stroke, alpha);
      L.strokePoly(subs[0].pts.map(p => apply(tx, p.x, p.y)), sw / 2, true);
