        if (cov <= 0) continue;
        const ia = accA[i];
        const outA = cov + ia * (1 - cov);
        if (outA <= 0) continue;
        acc[i * 3] = (cr * cov + acc[i * 3] * ia * (1 - cov)) / outA;
        acc[i * 3 + 1] = (cg * cov + acc[i * 3 + 1] * ia * (1 - cov)) / outA;
        acc[i * 3 + 2] = (cb * cov + acc[i * 3 + 2] * ia * (1 - cov)) / outA;
        accA[i] = outA;
      }
    }
    const img = Buffer.alloc(W * H * 4);
    for (let i = 0; i < W * H; i++) { img[i * 4] = Math.round(acc[i * 3]); img[i * 4 + 1] = Math.round(acc[i * 3 + 1]); img[i * 4 + 2] = Math.round(acc[i * 3 + 2]); img[i * 4 + 3] = 255; }
