function render(svgXml, opts = {}) {
  const roots = parseSVG(svgXml);
  const svgRoot = roots.find(r => r.name === 'svg') || roots[0];
  const w = opts.w || parseFloat(svgRoot.attrs.width) || 600;
  const h = opts.h || parseFloat(svgRoot.attrs.height) || 300;
  const r = new Renderer(w, h);
  const patterns = {};
  (function walk(n) { for (const node of n) { if (node.name === 'pattern') patterns[node.attrs.id] = node; walk(node.children); } })(roots);
  // handle pattern href/b chaining: b references a
  for (const id in patterns) {
    const p = patterns[id];
    const ref = p.attrs['xlink:href'] || p.attrs.href;
    if (ref) {
      const src = patterns[ref.startsWith('#') ? ref.slice(1) : ref];
      if (src) p.children = src.children;
    }
  }
  r.patterns = patterns;
  const viewport = svgRoot.attrs.viewBox;
  const rootTx = ident();
  r.renderSubtree(roots, rootTx, 1);
  return pngEncode(w, h, r.composite());
}

module.exports = { render, parsePath };

