// Render an SVG and print an ASCII overview at a reduced grid.
'use strict';
const { render, parsePath } = require('./render.js');

function nearestName(r, g, b) {
  const colors = {
    'B': [0, 0, 0],
    'W': [255, 255, 255],
    'Y': [216, 216, 108],   // #d8d86c
    'K': [125, 125, 35],    // #7d7d23
    'O': [244, 240, 235],   // off-white / near #d8d86c lightened
    'G': [128, 128, 128],
  };
  let best = '?', bd = 1e9;
  for (const k in colors) {
    const [cr, cg, cb] = colors[k];
    const d = (r - cr) ** 2 + (g - cg) ** 2 + (b - cb) ** 2;
    if (d < bd) { bd = d; best = k; }
  }
  return best;
}

function ascii(svgXml, opts = {}) {
  const w = opts.w || 600, h = opts.h || 300;
  const img = render(svgXml, { w, h });
  const cols = opts.cols || 120;
  const rows = opts.rows || Math.max(20, Math.round((cols * h / w) * 0.5));
  const cw = w / cols, ch = h / rows;
  const out = [];
  for (let ry = 0; ry < rows; ry++) {
    let line = '';
    for (let cx = 0; cx < cols; cx++) {
      let r = 0, g = 0, b = 0, n = 0;
      for (let dy = 0; dy < ch; dy += 2) {
        for (let dx = 0; dx < cw; dx += 2) {
          const px = Math.min(w - 1, Math.round(cx * cw + dx));
          const py = Math.min(h - 1, Math.round(ry * ch + dy));
          const idx = (py * w + px) * 4;
          r += img[idx]; g += img[idx + 1]; b += img[idx + 2]; n++;
        }
      }
      line += nearestName(r / n, g / n, b / n);
    }
    out.push(line);
  }
  return out.join('\n');
}

module.exports = { ascii };

