// Generates a clean bold "Z" closed polygon by offsetting a centerline polyline
// with miter joins, then writes it (rounded) as a path `d` string.
'use strict';

function fmt(n) {
  return Math.round(n * 100) / 100;
}

// offset a polyline by ±h on each side with miter joins; returns [leftPoints, rightPoints]
function offsetPolyline(pts, h) {
  const n = pts.length;
  // compute per-segment normals
  const mids = [];
  for (let i = 0; i < n - 1; i++) {
    const a = pts[i], b = pts[i + 1];
    let dx = b.x - a.x, dy = b.y - a.y;
    const len = Math.hypot(dx, dy);
    dx /= len; dy /= len;
    mids.push({ nx: -dy, ny: dx });
  }
  // vertex offset directions (average of adjacent normals, mitered)
  const left = [], right = [];
  for (let i = 0; i < n; i++) {
    const prevN = mids[Math.max(0, i - 1)];
    const nextN = mids[Math.min(n - 2, i)];
    // miter direction = normalize(prevN + nextN)
    let mx = prevN.nx + nextN.nx, my = prevN.ny + nextN.ny;
    const mlen = Math.hypot(mx, my);
    if (mlen < 1e-9) { mx = prevN.nx; my = prevN.ny; }
    else { mx /= mlen; my /= mlen; }
    // miter length: h / sin(halfAngle) ; halfAngle determined by dot of normals
    const cosHalf = Math.max(-1, Math.min(1, (prevN.nx * nextN.nx + prevN.ny * nextN.ny)));
    const halfAngle = Math.acos(cosHalf) / 2;
    const miterLen = h / Math.cos(halfAngle);
    left.push({ x: pts[i].x + mx * miterLen, y: pts[i].y + my * miterLen });
    right.push({ x: pts[i].x - mx * miterLen, y: pts[i].y - my * miterLen });
  }
  return { left, right };
}

function buildZ({ xl, xr, yt, yb, barT, diagD }) {
  const ytc = yt + barT / 2;
  const ybc = yb - barT / 2;
  const centerline = [
    { x: xl, y: ytc },
    { x: xr, y: ytc },
    { x: xl + diagD, y: ybc },
    { x: xr, y: ybc },
  ];
  const { left, right } = offsetPolyline(centerline, barT / 2);
  // outline: start at bottom-left outer corner going up the left edge, then around counterclockwise
  // left goes: P0 left, P1 left, P2 left, P3 left ; right goes: P0 right ... P3 right
  // We want the outline: (P0 right) -> (P1 right) [top edge] -> (P2 right)[diag upper-right] -> (P3 right)[bottom bar right]
  // -> then back along bottom: (P3 left) -> (P2 left)[diag lower-left] -> (P1 left) -> (P0 left) -> close
  const outline = [
    ...right,       // P0R, P1R, P2R, P3R
    ...left.reverse(), // P3L, P2L, P1L, P0L
  ];
  let d = 'M' + fmt(outline[0].x) + ' ' + fmt(outline[0].y);
  for (let i = 1; i < outline.length; i++) {
    d += 'L' + fmt(outline[i].x) + ' ' + fmt(outline[i].y);
  }
  d += 'Z';
  return d;
}

module.exports = { buildZ };

