const { render } = require('./render.js');

function whiteBBox(svg, w, h) {
  const { rgba } = render(svg, { w, h, raw: true });
  let minX = 1e9, minY = 1e9, maxX = -1, maxY = -1;
  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) {
    const i = (y * w + x) * 4;
    if (rgba[i] > 240 && rgba[i + 1] > 240 && rgba[i + 2] > 240) {
      if (x < minX) minX = x; if (x > maxX) maxX = x;
      if (y < minY) minY = y; if (y > maxY) maxY = y;
    }
  }
  return { minX, minY, maxX, maxY };
}

function buildSVG(d) {
  return '<svg width="600" height="300"><rect width="600" height="300" fill="#d8d86c"/>' +
    '<g transform="scale(3.77953 3.77929)"><g transform="matrix(.356 0 0 .345 123.85 85.93)">' +
    '<path fill="#fff" stroke="#7d7d23" stroke-width="9.06" d="' + d + '"/></g></g></svg>';
}

function generate({ xl, xr, yt, yb, barT, diagD }) {
  return buildZ({ xl, xr, yt, yb, barT, diagD });
}

module.exports = { whiteBBox, buildSVG, generate };

if (require.main === module) {
  const target = { minX: 309, minY: 123, maxX: 380, maxY: 216 };
  let p = { xl: -119, xr: -65, yt: -155, yb: -83, barT: 13, diagD: 14.7 };
  for (let iter = 0; iter < 40; iter++) {
    const d = generate(p);
    const bb = whiteBBox(buildSVG(d), 600, 300);
    const cx = (bb.minX + bb.maxX) / 2, cy = (bb.minY + bb.maxY) / 2;
    const tcx = (target.minX + target.maxX) / 2, tcy = (target.minY + target.maxY) / 2;
    // device-> inner: x_inner = (x_dev/3.77953 - 123.85)/0.356
    const dx = (tcx - cx) / 3.77953 / 0.356;
    const dy = (tcy - cy) / 3.77929 / 0.345;
    const dwx = (target.maxX - target.minX) - (bb.maxX - bb.minX);
    const dwy = (target.maxY - target.minY) - (bb.maxY - bb.minY);
    if (Math.abs(dx) < 0.05 && Math.abs(dy) < 0.05 && Math.abs(dwx) < 0.3 && Math.abs(dwy) < 0.3) {
      console.log('converged after', iter, JSON.stringify(p));
      console.log('bbox', JSON.stringify(bb));
      console.log('d=', JSON.stringify(d));
      break;
    }
    p.xl += dx; p.xr += dx;
    p.yt += dy; p.yb += dy;
    p.barT += (dwx / 3.77929 / 0.345);
    if (iter === 39) { console.log('last bbox', JSON.stringify(bb), JSON.stringify(p)); }
  }
}

